import React, { useState, useRef } from 'react';
import axios from 'axios';
import './App.css';

interface NotationRow {
  id: string;
  type: 'header' | 'notation';
  content?: string;
  cells?: string[];
}

const App: React.FC = () => {
  const [title, setTitle] = useState('Marathi Music Notation');
  const [rows, setRows] = useState<NotationRow[]>([
    { id: '1', type: 'header', content: 'Gat' },
    { id: '2', type: 'notation', cells: Array(16).fill('') }
  ]);
  const [activeCell, setActiveCell] = useState<{ rowId: string, cellIndex: number } | null>(null);

  const swaras = ['सा', 'रे', 'ग', 'म', 'प', 'ध', 'नि'];
  const komalTeevra = ['रे॒', 'ग॒', 'म॑', 'ध॒', 'नि॒'];
  const others = ['-', '.', ' '];

  const addRow = (type: 'header' | 'notation') => {
    const newRow: NotationRow = {
      id: Date.now().toString(),
      type,
      content: type === 'header' ? 'New Section' : '',
      cells: type === 'notation' ? Array(16).fill('') : undefined
    };
    setRows([...rows, newRow]);
  };

  const deleteRow = (id: string) => {
    setRows(rows.filter(row => row.id !== id));
  };

  const updateHeader = (id: string, content: string) => {
    setRows(rows.map(row => row.id === id ? { ...row, content } : row));
  };

  const updateCell = (id: string, index: number, value: string) => {
    // Limit to 2 characters as requested
    if (value.length > 5) return; // Increased slightly for Marathi characters + markers
    setRows(rows.map(row => {
      if (row.id === id && row.cells) {
        const newCells = [...row.cells];
        newCells[index] = value;
        return { ...row, cells: newCells };
      }
      return row;
    }));
  };

  const appendToActiveCell = (char: string) => {
    if (!activeCell) return;
    const row = rows.find(r => r.id === activeCell.rowId);
    if (row && row.cells) {
      const currentVal = row.cells[activeCell.cellIndex];
      updateCell(activeCell.rowId, activeCell.cellIndex, currentVal + char);
    }
  };

  const exportData = async (format: 'txt' | 'docx' | 'pdf') => {
    try {
      const response = await axios.post(`http://localhost:5000/api/export/${format}`, {
        title,
        rows
      }, { responseType: 'blob' });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `notation.${format}`);
      document.body.appendChild(link);
      link.click();
    } catch (error) {
      console.error('Export failed:', error);
      alert('Export failed. Make sure the backend is running.');
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>Marathi Music Notation Tool</h1>
        <div className="title-input">
          <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Enter Title" />
        </div>
        <div className="export-buttons">
          <button onClick={() => exportData('txt')}>Download TXT</button>
          <button onClick={() => exportData('docx')}>Download DOCX</button>
          <button onClick={() => exportData('pdf')}>Download PDF</button>
        </div>
      </header>

      <main>
        <div className="taal-header-visual">
          <h3>Taal: Teental (16 Beats)</h3>
          <div className="taal-grid">
            <div className="taal-row">
              {['1','2','3','4','5','6','7','8'].map(b => <div key={b} className="taal-cell">{b}</div>)}
            </div>
            <div className="taal-row">
              {['धा','धिन्','धिन्','धा','धा','धिन्','धिन्','धा'].map((n, i) => <div key={i} className="taal-cell">{n}</div>)}
            </div>
            <div className="taal-row markers">
              {['x','','','','2','','',''].map((m, i) => <div key={i} className="taal-cell">{m}</div>)}
            </div>
          </div>
        </div>

        <div className="notation-area">
          {rows.map((row) => (
            <div key={row.id} className={`row-container ${row.type}`}>
              <button className="delete-btn" onClick={() => deleteRow(row.id)}>×</button>
              {row.type === 'header' ? (
                <input 
                  className="header-input" 
                  value={row.content} 
                  onChange={(e) => updateHeader(row.id, e.target.value)}
                />
              ) : (
                <div className="notation-grid">
                  {row.cells?.map((cell, idx) => (
                    <input
                      key={idx}
                      className={`cell-input ${activeCell?.rowId === row.id && activeCell?.cellIndex === idx ? 'active' : ''}`}
                      value={cell}
                      onFocus={() => setActiveCell({ rowId: row.id, cellIndex: idx })}
                      onChange={(e) => updateCell(row.id, idx, e.target.value)}
                    />
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>

        <div className="controls">
          <button onClick={() => addRow('header')}>Add Header (Gat/Tana)</button>
          <button onClick={() => addRow('notation')}>Add Notation Row</button>
        </div>

        <div className="keyboard">
          <h3>Marathi Music Keyboard</h3>
          <div className="keyboard-section">
            {swaras.map(s => <button key={s} onClick={() => appendToActiveCell(s)}>{s}</button>)}
          </div>
          <div className="keyboard-section">
            {komalTeevra.map(s => <button key={s} onClick={() => appendToActiveCell(s)}>{s}</button>)}
          </div>
          <div className="keyboard-section">
            {others.map(s => <button key={s} onClick={() => appendToActiveCell(s)}>{s === ' ' ? 'Space' : s}</button>)}
            <button onClick={() => {
              if (activeCell) {
                const row = rows.find(r => r.id === activeCell.rowId);
                if (row && row.cells) {
                  updateCell(activeCell.rowId, activeCell.cellIndex, '');
                }
              }
            }}>Clear</button>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;
